    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_3,'speak',17,NULL,NULL,'هنگام معاینه از تو می‌خواهند نفس عمیق بکشی؛ بگو دستور را انجام می‌دهی.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"هنگام معاینه از تو می‌خواهند نفس عمیق بکشی؛ بگو دستور را انجام می‌دهی.","scenario_fa":"هنگام معاینه از تو می‌خواهند نفس عمیق بکشی؛ بگو دستور را انجام می‌دهی.","accepted":["Ich atme jetzt tief ein.","Ja, ich hole tief Luft."],"acceptedIntents":["Ich atme jetzt tief ein.","Ja, ich hole tief Luft."],"accepted_intents":["Ich atme jetzt tief ein.","Ja, ich hole tief Luft."],"input":"speech","audioRequired":false,"textVisible":false,"scored":true,"independent":true,"masteryCheck":false,"cumulativeMastery":false}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',15));
    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_3,'speak',18,NULL,NULL,'دوستت نتیجهٔ معاینه را می‌پرسد؛ بگو سرما خورده‌ای اما داروی قوی لازم نداری.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"دوستت نتیجهٔ معاینه را می‌پرسد؛ بگو سرما خورده‌ای اما داروی قوی لازم نداری.","scenario_fa":"دوستت نتیجهٔ معاینه را می‌پرسد؛ بگو سرما خورده‌ای اما داروی قوی لازم نداری.","accepted":["Ich habe eine Erkältung, aber ich brauche kein starkes Medikament.","Es ist nur eine Erkältung und ich brauche keine starke Medizin."],"acceptedIntents":["Ich habe eine Erkältung, aber ich brauche kein starkes Medikament.","Es ist nur eine Erkältung und ich brauche keine starke Medizin."],"accepted_intents":["Ich habe eine Erkältung, aber ich brauche kein starkes Medikament.","Es ist nur eine Erkältung und ich brauche keine starke Medizin."],"input":"speech","audioRequired":false,"textVisible":false,"scored":true,"independent":true,"masteryCheck":false,"cumulativeMastery":false}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',15));
    INSERT INTO lessons (chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES (v_chapter,v_c_lena,v_c_raha,'Der Plan für zu Hause','برنامهٔ خانه','Raha receives a sick note, organizes her recovery at home, and knows when she should contact the practice again.','رها گواهی بیماری می‌گیرد، برنامهٔ بهبودش در خانه را تنظیم می‌کند و می‌داند چه زمانی باید دوباره با مطب تماس بگیرد.','story','berlin_new_start',60,1,760,4,'validated',JSON_OBJECT('series',15,'lesson',4,'chapterRole','review_transfer_and_chapter_mastery','newUnitQuota',5,'typingRequired',FALSE,'reviewOffsets',JSON_ARRAY(1,2,4,8,16),'chapterMastery',TRUE,'cumulativeMastery',FALSE)); SET v_l_4=LAST_INSERT_ID();
