    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'speak',12,v_t_8,NULL,'بله، آن وقت یک وقت تازه می‌گیرم.','بدون دیدن متن آلمانی، پاسخ را با صدای خودت بگو.',1,CAST('{"mode":"recall_hidden","cue_fa":"بله، آن وقت یک وقت تازه می‌گیرم.","cueFa":"بله، آن وقت یک وقت تازه می‌گیرم.","accepted":["Ja, dann vereinbare ich einen neuen Termin.","Dann rufe ich den Arzt wieder an.","Bei Fieber brauche ich einen neuen Termin."],"input":"speech","audioReveal":"after_attempt","textVisible":false,"scored":true,"independent":true}' AS JSON),JSON_OBJECT('contractMode','recall_hidden','typing',FALSE,'series',15));
